import asyncio, os, signal, sys, threading, time
sys.path.insert(0,'/app')

events=[]
def make(i):
    async def task():
        try:
            await asyncio.sleep(5)
        finally:
            events.append(f'cleanup-start-{i}')
            try:
                await asyncio.sleep(0.3)
            except BaseException as e:
                events.append(f'cleanup-int-{i}-{type(e).__name__}')
                raise
            events.append(f'cleanup-done-{i}')
    return task

async def run_tasks(tasks, max_concurrent):
    sem=asyncio.Semaphore(max_concurrent)
    async def one(m):
        async with sem: await m()
    running=[asyncio.ensure_future(one(t)) for t in tasks]
    try:
        await asyncio.gather(*running)
    except BaseException as e:
        events.append(f'caught-{type(e).__name__}')
        for f in running: f.cancel()
        for f in running:
            while not f.done():
                try:
                    await asyncio.shield(f)
                except BaseException as e2:
                    events.append(f'shield-caught-{type(e2).__name__}-done={f.done()}')
        raise

async def main():
    await run_tasks([make(i) for i in range(3)],3)

def send():
    time.sleep(0.2); os.kill(os.getpid(),signal.SIGINT)
    time.sleep(0.1); os.kill(os.getpid(),signal.SIGINT)
threading.Thread(target=send,daemon=True).start()
try: asyncio.run(main())
except BaseException as e: events.append(f'exit-{type(e).__name__}')
print(chr(10).join(events))
